"""Seed for data/shortlist.json (Deliverable B): 30 priority dossiers for Phase 2.
Scores: H / M / L. museum = presence in museum collections/exhibitions found in this pass; influence = documented historical role;
collecting = prominence in the collectors' literature/market (market sources never decide attribution, only relevance);
documentation = what is available to write a sourced dossier (A/B sources read or identified)."""
def X(n, title, ids, museum, influence, collecting, docs, why, key):
    return dict(id=f"DOS-{n:02d}", rank=n, title=title, entity_ids=ids,
                scores=dict(museum_relevance=museum, historical_influence=influence, collecting_relevance=collecting, documentation_availability=docs),
                motivation=why, key_source_ids=key)
